/** Пояснения наблюдателю; они не становятся входами или правилами мозга. */
export const BRAIN_COMPONENTS=Object.freeze([
 ['context','Главный контекст — изменяемая структура','Объединяет тело, сводку видимых клеток, личную память и текущий процесс. Скрытые нейроны и связи этого блока эволюционируют при рождении; за жизнь обучаются веса. Его 16 выходов — внутренние признаки ситуации, без заранее назначенного смысла «голод», «еда» или «опасность».'],
 ['cells','Кодировщик клеток','Одна и та же небольшая сеть обрабатывает каждую видимую клетку отдельно: своё место и соседние гексы. Из её 8 выходов рассчитываются средние и средние квадраты для главного контекста. Число выхода кодировщика не обозначает конкретную клетку.'],
 ['target','Проекция цели','Преобразует признаки одного рассматриваемого варианта: место назначения, пищу, память об этом месте, продолжение и цену действия. Выходы «Цель 1…16» — обучаемые внутренние компоненты, а не 16 мест назначения. Они взаимодействуют с соответствующими выходами контекста и проекции операции.'],
 ['operation','Проекция операции','Преобразует тип предлагаемого действия в 16 компонентов оценки. Направления движения выбираются внутри операции «Переместиться». «Операции 1…16» — внутренние компоненты, а не номера действий.'],
 ['direct','Прямая оценка','Преобразует признаки варианта в отдельную добавку к Q. Без скрытых слоёв это линейная сумма; в новой схеме могут появиться нелинейные скрытые слои. Этот короткий путь действует вместе с контекстом и проекциями; положительный вес повышает вклад признака, отрицательный понижает.'],
 ['gate','Диспетчер внимания — изменяемая структура','Наследуемая сеть проверяет процесс или покой и запрашивает основной выбор при положительном выходе. Её нейроны и связи эволюционируют при рождении, веса за жизнь не обучаются. Дополнительный вход давности уменьшается после основного решения; проверки диспетчера его не сбрасывают.'],
].map(Object.freeze));
export const BRAIN_LEGEND='Зелёная связь — положительный действующий вес; жёлтая — отрицательный; серая — нулевой. Нулевой вес существующей связи может обучаться. Белым и вдвое толще отмечены выбранная связь или связи выбранного нейрона. Голубые кружки — входы; золотистые — скрытые нейроны и выходы; белый кружок выбран. Прямые линии могут пропускать уровни. Схема показывает устройство и веса, а не текущие активации. Просмотр не вызывает мозг и не меняет опыт.';
export function brainFeatureExplanation(label,component='context',input=true){
 if(!input){
  if(label.startsWith('Скрытый'))return 'Нелинейный нейрон tanh: складывает взвешенные входы и смещение, затем ограничивает активацию от −1 до +1. Его смысл возникает при эволюции и обучении.';
  if(component==='gate')return label.startsWith('Контроллер')?'Скрытый нейрон контроллера, активация tanh от −1 до +1.':'Линейный выход: значение больше нуля запрашивает основной мозг. Это не вероятность.';
  if(component==='cells')return 'Одна из восьми обучаемых характеристик клетки, tanh от −1 до +1. Номер не закреплён за конкретным свойством.';
  if(component==='direct')return 'Скалярная линейная добавка к Q — прогнозу субъективного подкрепления. Q не является вероятностью выживания.';
  return 'Внутренняя компонента с этим номером. Итог: Q = сумма(контекст × операция × цель) / √16 + прямая оценка. Положительное или отрицательное число само по себе не означает полезную стратегию.';
 }
 if(label.startsWith('Процесс: '))return 'Сведения о собственном текущем или последнем процессе. '+brainFeatureExplanation(label.slice(9),component,true);
 if(label.startsWith('Операция: '))return 'Признак рассматриваемого типа действия: 1 для этого типа, 0 для остальных. '+brainFeatureExplanation(label.slice(10),component,true);
 if(label.startsWith('Движутся: '))return 'Количество других особей на рассматриваемой клетке, которые сейчас движутся в направлении «'+label.slice(10)+'» относительно взгляда наблюдателя. Направление — не глобальный север. Количество преобразуется функцией плотности n/(n+1); это наблюдение, а не инструкция следовать за ними.';
 if(label==='Есть целевая особь')return 'У варианта есть наблюдаемая особь: ребёнок при кормлении либо цель атаки. Её ID не является числовым входом.';
 if(label==='Размер целевой особи / сумму размеров')return 'Размер наблюдаемой особи / (её размер + собственный размер). Энергия и желудок цели не раскрываются.';
 if(label==='Относительное здоровье целевой особи')return 'Наблюдаемая доля здоровья цели. При кормлении это ребёнок, при атаке — выбранная особь.';
 if(label.startsWith('Целевая особь'))return 'Признак видимой деятельности целевой особи, её ношения либо направления замаха. Это текущее наблюдение, а не скрытое намерение.';
 if(label==='Есть носимый ребёнок')return 'Родитель знает, несёт ли он своего ребёнка. Это собственное состояние, а не сведения обо всех семьях мира.';
 if(label==='Размер ребёнка / сумму размеров')return 'Наблюдаемый размер собственного ребёнка / (размер ребёнка + размер родителя). Энергия и желудок ребёнка в сеть не передаются.';
 if(label==='Относительное здоровье ребёнка')return 'Видимая доля здоровья собственного носимого ребёнка. Кормление может повлиять на неё через последующее питание и рост.';
 if(label==='Остаток срока ношения')return 'Доля оставшегося срока, зафиксированного при рождении ребёнка. По окончании ребёнок становится самостоятельным.';
 if(label.startsWith('Выполняют: '))return 'Количество других особей на рассматриваемой клетке с текущим действием «'+label.slice(11)+'», преобразованное как n/(n+1). Направления движения отсчитываются относительно взгляда наблюдателя. Собственная особь исключена. Намерения и личности не раскрываются.';
 if(label==='Относительное q'||label==='Относительное r'||label==='Направление q'||label==='Направление r')return 'Одна из двух осей q/r шестиугольной сетки в личной системе координат. У своей клетки (0, 0), у соседней — смещение вдоль этих осей. Это направление относительно жителя, без глобальных координат мира.';
 if(label==='Тело / (тело + опорная масса)')return 'Масса тканей L / (L + L₀): при опорной массе даёт 0,5. Большие тела различаются без отсечения на 1.';
 if(label==='Рекордная масса / (рекордная + опорная)')return 'Исторический максимум M / (M + L₀). Рекорд не уменьшается при истощении.';
 if(label==='Тело / исторический максимум')return 'Доля сохранившихся тканей L / M. Она уменьшается при катаболизме и восстанавливается при росте.';
 if(label==='Возраст / (возраст + срок развития)')return 'Возраст / (возраст + округлённый срок взросления). В срок взросления равен 0,5; далее плавно приближается к 1.';
 if(label==='Желудок / текущий объём')return 'Занятый объём пищевых групп W / V. Усвоенная группа занимает место до срока выведения.';
 if(label==='Есть жертва')return '1 для варианта с конкретной видимой жертвой, 0 для остальных вариантов.';
 if(label==='Размер жертвы / сумму размеров')return 'Размер жертвы / (её размер + собственный размер). Равные тела дают 0,5.';
 if(label==='Относительное здоровье жертвы')return 'Видимая доля H / Hmax жертвы. Её энергия и геном недоступны.';
 if(label==='Энергия / текущая ёмкость')return 'Доля нынешней энергетической ёмкости тела. Полный запас даёт 1 при любом размере жителя.';
 if(label==='Здоровье / текущий максимум')return 'Относительное здоровье собственного тела: H / Hmax. Потеря тканей изменяет и максимум, поэтому мозг получает долю.';
 if(label.startsWith('Прогноз травы')||label.startsWith('Прогноз плодов')||label.startsWith('Прогноз мяса'))return 'Личная оценка количества этого типа пищи по прежним наблюдениям. Скрытая клетка не обновляет память; уверенность падает со временем.';
 if(label.startsWith('Жертва:'))return 'Наблюдаемое действие конкретной особи на своей клетке. Это внешний признак, а не чтение скрытых намерений.';
 if(label.startsWith('Жертва атакует'))return 'Видимое направление замаха: на наблюдателя или на другого жителя. Числовой ID жертвы в сеть не передаётся.';
 if(label.startsWith('Выбран тип:'))return 'Тип пищи рассматриваемого варианта сбора, еды или выкладывания: 1 для выбранного типа, 0 для остальных.';
 if(label.includes('Беременность')||label.includes('беременности')||label==='Роды')return 'Собственное состояние вынашивания/родов. Оплаченная доля определяет долю планового тела ребёнка; геном плода не является наблюдением.';
 if(label.startsWith('Трава')||label.startsWith('Плоды')||label.startsWith('Мясо'))return 'Наблюдаемое количество указанного типа пищи, нормированное по подписи. Разные типы имеют собственные мощность усвоения и энергетическую ценность.';
 if(label.startsWith('Энергия /'))return 'Собственная энергия, делённая на 100: при энергии 50 вход равен 0,5. Вход передаёт состояние, но не заставляет сохранять энергию.';
 if(label.startsWith('Здоровье /'))return 'Собственное здоровье, делённое на 100. Направление субъективной ценности определяется наследуемой чувствительностью.';
 if(label==='Запас / вместимость')return 'Переносимые порции, делённые на вместимость запаса. Это пища при себе, ещё не в желудке.';
 if(label==='Желудок / вместимость')return 'Содержимое желудка, делённое на его вместимость. Это отдельно от энергии и переносимого запаса.';
 if(label.includes('Пища')&&label.includes('/ 10'))return 'Количество видимых порций на клетке, делённое на 10: пять порций дают 0,5. Вход ограничен от −1 до +1, поэтому десять и более порций здесь не различаются.';
 if(label.includes('Прогноз пищи'))return 'Оценка пищи по личной записи памяти, делённая на 10 и ограниченная диапазоном входа. Это прогноз из прежних наблюдений, а не скрытая информация о клетке.';
 if(label.startsWith('Средняя активация'))return 'Среднее значение указанного выхода кодировщика по всем видимым клеткам. Это сводка обзора, а не отдельная клетка.';
 if(label.startsWith('Средний квадрат'))return 'Среднее квадратов указанного выхода кодировщика. Вместе со средним помогает различать однородный и неоднородный обзор; само по себе это не дисперсия.';
 if(label==='Число клеток')return 'Количество клеток обзора n, преобразованное как n/(n+1). У границы карты доступно меньше клеток.';
 if(label.startsWith('Потенциал пищи'))return 'Сводная оценка по личной памяти для своего места (номер 0) или одного из шести соседних направлений (1–6). Это не готовая цель и не реальная скрытая пища.';
 if(label.includes('Уверенность'))return 'Уверенность личной записи памяти; это не вероятность успеха действия. При отсутствии записи значение равно нулю.';
 if(label==='Есть запись'||label==='Есть запись цели')return '1, если у жителя есть личная запись об этой клетке; иначе 0. Память не даёт автоматического знания всей карты.';
 if(label.includes('Источник')||label==='Есть источник')return 'Признак видимого источника пищи: 1 или 0. Источник может быть пустым; количество лежащей пищи передаётся отдельно.';
 if(label==='Вода')return '1 для воды, 0 для суши на наблюдаемой клетке. Доступность перемещения отдельно определяет физика мира.';
 if(label==='Своя клетка'||label==='Цель — своя клетка')return '1, если рассматриваемая клетка совпадает с текущим местом жителя; иначе 0.';
 if(['Плотность других','Другие в цели','Другие здесь','Другие в обзоре'].includes(label))return 'Количество других особей, сжатое функцией плотности n/(n+1). Для обзора используется общее число видимых других; собственная особь исключена.';
 if(label==='Повтор деятельности')return '1, если рассматриваемый вариант повторяет прежнюю деятельность, иначе 0. Сам по себе признак не заставляет повторять её.';
 if(label==='Давность записи')return 'Время с последнего наблюдения цели, делённое на наследуемый масштаб старения памяти; значение ограничено диапазоном входа.';
 if(label==='Градиент пищи')return 'Разность оценок потенциала памяти между соседним направлением и своим местом. Показывает изменение личного прогноза, а не точный путь к пище.';
 if(label==='Неопределённость')return 'Неопределённость прогноза памяти о цели. Неизвестность не получает обязательной награды за исследование.';
 if(label==='Непосещённое место')return '1 при включённой памяти, если запись отсутствует либо место ещё не посещалось; иначе 0.';
 if(label==='Процесс продолжается'||label==='Продолжение попытки')return '1, если процесс активен или вариант продолжает текущую попытку с сохранением прогресса; иначе 0.';
 if(label==='Прогресс')return 'Доля выполненного текущего процесса: от 0 до 1. Это не вероятность его завершения.';
 if(label==='Осталось / 20'||label==='Время / 20')return 'Оставшаяся или планируемая длительность действия в подшагах, делённая на 20. Одна Т содержит десять подшагов.';
 if(label==='Цена решения / 0,10')return 'Рассчитанная энергетическая цена выбора для данного мозга, делённая на 0,10. Ставка повтора и вычислительная структура меняют этот вход; последующее обучение оплачивается отдельно.';
 if(label.startsWith('Вызов: '))return 'Один из признаков причины обращения к основному мозгу: завершение процесса, добровольный пересмотр контроллером либо физический срыв.';
 if(label.startsWith('Изменилась')||label.startsWith('Изменились'))return 'Флаг изменения видимых условий по сравнению с предыдущим снимком контроллера: 1 при изменении, иначе 0. Скрытые клетки не проверяются.';
 if(label==='Пища здесь'||label==='Пища цели')return 'Видимое количество порций на своей клетке или цели процесса, делённое на 10. Контроллер получает только локальное наблюдение.';
 if(['Переместиться','Подобрать','Съесть','Ждать','Родить','Положить'].includes(label))return 'Один из шести типов действий. В группе признаков он равен 1 для рассматриваемого/текущего типа и 0 для остальных; допустимость определяет мир.';
 return 'Числовой признак локального наблюдения или собственного процесса. Его влияние задают веса всех последующих путей; отдельный положительный вес не является готовым правилом поведения.';
}
